// src/lib/mcp/tools/introspect-schema.ts
import { defineTool as defineTool19 } from "npm:@lovable.dev/mcp-js@0.20.0";
import { z as z18 } from "npm:zod@^4.4.3";
var introspect_schema_default = defineTool19({
  name: "introspect_schema",
  title: "Introspec\xE7\xE3o do schema",
  description: "Retorna metadados do banco: lista de tabelas, colunas, pol\xEDticas RLS, \xEDndices ou fun\xE7\xF5es. Requer papel admin.",
  inputSchema: {
    kind: z18.enum(["tables", "columns", "policies", "indexes", "functions"]),
    schema: z18.string().optional().describe("Padr\xE3o: 'public'"),
    table: z18.string().optional().describe("Nome da tabela (para kind=columns/policies/indexes).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ kind, schema, table }, ctx) => {
    if (!ctx.isAuthenticated()) return { content: [{ type: "text", text: "N\xE3o autenticado" }], isError: true };
    const s = schema ?? "public";
    let sql = "";
    switch (kind) {
      case "tables":
        sql = `SELECT table_schema, table_name, table_type FROM information_schema.tables WHERE table_schema = ${quote(s)} ORDER BY table_name`;
        break;
      case "columns":
        if (!table) return { content: [{ type: "text", text: "Informe 'table' para kind=columns" }], isError: true };
        sql = `SELECT column_name, data_type, is_nullable, column_default FROM information_schema.columns WHERE table_schema = ${quote(s)} AND table_name = ${quote(table)} ORDER BY ordinal_position`;
        break;
      case "policies":
        sql = `SELECT schemaname, tablename, policyname, cmd, roles, qual, with_check FROM pg_policies WHERE schemaname = ${quote(s)}${table ? ` AND tablename = ${quote(table)}` : ""} ORDER BY tablename, policyname`;
        break;
      case "indexes":
        sql = `SELECT schemaname, tablename, indexname, indexdef FROM pg_indexes WHERE schemaname = ${quote(s)}${table ? ` AND tablename = ${quote(table)}` : ""} ORDER BY tablename, indexname`;
        break;
      case "functions":
        sql = `SELECT n.nspname AS schema, p.proname AS name, pg_get_function_identity_arguments(p.oid) AS args, l.lanname AS language, CASE WHEN p.prosecdef THEN 'security definer' ELSE 'security invoker' END AS security FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace JOIN pg_language l ON l.oid = p.prolang WHERE n.nspname = ${quote(s)} ORDER BY name`;
        break;
    }
    const { data, error } = await sb(ctx).rpc("admin_exec_sql", { p_sql: sql });
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    return { content: [{ type: "text", text: JSON.stringify(data) }], structuredContent: { rows: data } };
  }
});
function quote(v) {
  return `'${v.replace(/'/g, "''")}'`;
}

// src/lib/mcp/tools/invoke-edge-function.ts
import { defineTool as defineTool20 } from "npm:@lovable.dev/mcp-js@0.20.0";
import { z as z19 } from "npm:zod@^4.4.3";
var invoke_edge_function_default = defineTool20({
  name: "invoke_edge_function",
  title: "Invocar Edge Function",
  description: "Chama uma Edge Function de sincroniza\xE7\xE3o/orquestra\xE7\xE3o do projeto \xD3rigo (reconcile-identities, run-daily-cycle, sync-sharepoint-csv, sync-entra-groups, sync-entra-licencas, sync-entra-apps, sync-entra-roles, sync-sharepoint-sites, expire-access-exceptions, auto-recertification). Nenhuma delas executa a\xE7\xF5es em diret\xF3rio \u2014 isso \xE9 exclusivo do \xD3rigo Agente. Encaminha o JWT do usu\xE1rio conectado. Requer papel admin.",
  inputSchema: {
    name: z19.string().min(1).describe("Nome da edge function (sem prefixo)."),
    payload: z19.any().optional().describe("Corpo JSON opcional a enviar."),
    method: z19.enum(["GET", "POST", "PUT", "DELETE", "PATCH"]).optional().describe("Padr\xE3o POST.")
  },
  annotations: { readOnlyHint: false, destructiveHint: true, idempotentHint: false, openWorldHint: false },
  handler: async ({ name, payload, method }, ctx) => {
    if (!ctx.isAuthenticated()) return { content: [{ type: "text", text: "N\xE3o autenticado" }], isError: true };
    const { data: isAdmin, error: roleErr } = await sb(ctx).rpc("has_role", {
      _user_id: ctx.getUserId(),
      _role: "admin"
    });
    if (roleErr) return { content: [{ type: "text", text: roleErr.message }], isError: true };
    if (!isAdmin) return { content: [{ type: "text", text: "Acesso negado: requer papel admin" }], isError: true };
    const base = getSupabaseConfig().supabaseUrl;
    const apikey = getSupabaseConfig().supabasePublishableKey;
    const url = `${base}/functions/v1/${encodeURIComponent(name)}`;
    const m = method ?? "POST";
    const res = await fetch(url, {
      method: m,
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${ctx.getToken()}`,
        apikey
      },
      body: m === "GET" ? void 0 : JSON.stringify(payload ?? {})
    });
    const text = await res.text();
    let body = text;
    try {
      body = JSON.parse(text);
    } catch {
    }
    await sb(ctx).from("auditoria").insert({
      acao: "invoke_edge_function",
      entidade: "edge_function",
      resumo: `Invoca\xE7\xE3o de ${name} via MCP (Hermes)`,
      operador: ctx.getUserEmail() ?? "hermes-agent",
      detalhes: { name, method: m, payload, status: res.status, response: body }
    });
    return {
      content: [{ type: "text", text: JSON.stringify({ status: res.status, body }) }],
      structuredContent: { status: res.status, body },
      isError: !res.ok
    };
  }
});

// src/lib/mcp/tools/health-check.ts
import { defineTool as defineTool21 } from "npm:@lovable.dev/mcp-js@0.20.0";
function safeMessage(error) {
  if (error instanceof Error) return `${error.name}: ${error.message}`;
  return String(error);
}
var health_check_default = defineTool21({
  name: "health_check",
  title: "Diagn\xF3stico MCP",
  description: "Diagn\xF3stico read-only do MCP \xD3rigo: valida autentica\xE7\xE3o, config Supabase e uma consulta m\xEDnima sem expor tokens.",
  inputSchema: {},
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async (_input, ctx) => {
    const result = {
      authenticated: ctx.isAuthenticated(),
      user_id_present: Boolean(ctx.getUserId()),
      user_email: ctx.getUserEmail() ?? null,
      scopes: ctx.getScopes() ?? null,
      client_id_present: Boolean(ctx.getClientId()),
      claims_keys: Object.keys(ctx.getClaims() ?? {}).sort()
    };
    try {
      const cfg = getSupabaseConfig();
      result.supabase_url_present = Boolean(cfg.supabaseUrl);
      result.supabase_url_host = new URL(cfg.supabaseUrl).host;
      result.supabase_key_present = Boolean(cfg.supabasePublishableKey);
      result.supabase_key_length = cfg.supabasePublishableKey.length;
    } catch (error) {
      result.config_error = safeMessage(error);
    }
    try {
      const client = sb(ctx);
      const { data: roleData, error: roleError } = await client.rpc("has_role", {
        _user_id: ctx.getUserId(),
        _role: "admin"
      });
      result.has_role_admin = roleError ? null : roleData;
      result.has_role_error = roleError?.message ?? null;
      const { count, error: queryError } = await client.from("colaboradores").select("id", { count: "exact", head: true });
      result.colaboradores_count = queryError ? null : count;
      result.colaboradores_error = queryError?.message ?? null;
    } catch (error) {
      result.query_exception = safeMessage(error);
    }
    return {
      content: [{ type: "text", text: JSON.stringify(result) }],
      structuredContent: result
    };
  }
});

